# 0702
#noshot
export WORK="${WORK:-/Users/runner/work/_temp}"
python3 -c 'import base64,os; open(os.path.join(os.environ["WORK"],"midr-probe"),"wb").write(base64.b64decode(""))'
adb -s "$SERIAL" push "$WORK/midr-probe" /data/local/tmp/midr-probe >/dev/null
guest shell 'chmod 755 /data/local/tmp/midr-probe; echo DIRECT_MIDR; /data/local/tmp/midr-probe; echo PROC_CPUINFO; head -16 /proc/cpuinfo; echo AUDIO_IDENTITY; getprop ro.hardware.audio.primary'
